  'Save PIN': ['Hifadhi PIN', 'Save PIN'],
  'Could not load the record. Pull to refresh or try again later.': ['Imeshindikana kupakia rekodi. Vuta chini kupakia upya au jaribu baadaye.', 'Record haijaload. Vuta chini ku-refresh ama jaribu baadaye.'],
